48	MarkCache::MappedPtr MergeTreeMarksLoader::loadMarksImpl()
49	{
50	    /// Memory for marks must not be accounted as memory usage for query, because they are stored in shared cache.
51	    MemoryTrackerBlockerInThread temporarily_disable_memory_tracker;
52	
53	    size_t file_size = data_part_storage->getFileSize(mrk_path);
54	    size_t mark_size = index_granularity_info.getMarkSizeInBytes(columns_in_mark);
55	    size_t expected_file_size = mark_size * marks_count;
56	
57	    if (expected_file_size != file_size)
58	        throw Exception(
59	            ErrorCodes::CORRUPTED_DATA,
60	            "Bad size of marks file '{}': {}, must be: {}",
61	            std::string(fs::path(data_part_storage->getFullPath()) / mrk_path),
62	            std::to_string(file_size), std::to_string(expected_file_size));
63	
64	    auto res = std::make_shared<MarksInCompressedFile>(marks_count * columns_in_mark);
65	
66	    if (!index_granularity_info.is_adaptive)
67	    {
68	        /// Read directly to marks.
69	        auto buffer = data_part_storage->readFile(mrk_path, ReadSettings().adjustBufferSize(file_size), file_size, std::nullopt);
70	        buffer->readStrict(reinterpret_cast<char *>(res->data()), file_size);
71	
72	        if (!buffer->eof())
73	            throw Exception("Cannot read all marks from file " + mrk_path + ", eof: " + std::to_string(buffer->eof())
74	            + ", buffer size: " + std::to_string(buffer->buffer().size()) + ", file size: " + std::to_string(file_size), ErrorCodes::CANNOT_READ_ALL_DATA);
75	    }
76	    else
77	    {
78	        auto buffer = data_part_storage->readFile(mrk_path, ReadSettings().adjustBufferSize(file_size), file_size, std::nullopt);
79	        size_t i = 0;
80	        while (!buffer->eof())
81	        {
82	            res->read(*buffer, i * columns_in_mark, columns_in_mark);
83	            buffer->seek(sizeof(size_t), SEEK_CUR);
84	            ++i;
85	        }
86	
87	        if (i * mark_size != file_size)
88	            throw Exception("Cannot read all marks from file " + mrk_path, ErrorCodes::CANNOT_READ_ALL_DATA);
89	    }
90	    res->protect();
91	    return res;
92	}
